pub struct Vault {            // public type, private fields: the enclosure
    store: Store,             // unreachable outside this module
    policy: Policy,
}

impl Vault {
    pub fn read(&self, who: &Subject, id: Id) -> Result<Record, Denied> {
        if !self.policy.allows(who, id) {
            return Err(Denied(id));      // decision precedes the access
        }
        self.store.load(id)              // &self; Store never moves out
    }
}
